26	TracePlot::TracePlot(TraceModel &model, QWidget *parent)
27	    : QWidget(parent),
28	      model(model),
29	      selectedMarker(nullptr),
30	      movingGraph(false),
31	      traceRemovalPending(false),
32	      dropPending(false),
33	      dropTrace(nullptr),
34	      marginTop(20),
35	      limitPassing(true)
36	{
37	    parentTile = nullptr;
38	
39	    contextmenu = new QMenu();
40	    markedForDeletion = false;
41	    setSizePolicy(QSizePolicy::Expanding, QSizePolicy::Expanding);
42	    lastUpdate = QTime::currentTime();
43	    replotTimer.setSingleShot(true);
44	    connect(&replotTimer, &QTimer::timeout, this, qOverload<>(&TracePlot::update));
45	    TracePlot::updateSpan(model.getSpanStart(), model.getSpanStop());
46	    xSweep = std::numeric_limits<double>::quiet_NaN();
47	    // get notified when the span changes
48	    connect(&model, &TraceModel::SpanChanged, this, qOverload<double, double>(&TracePlot::updateSpan));
49	    plots.insert(this);
50	
51	    cursorLabel = new QLabel("Test", this);
52	    cursorLabel->hide();
53	    setMouseTracking(true);
54	    setAcceptDrops(true);
55	}
56	
57	TracePlot::~TracePlot()
58	{
59	    plots.erase(this);
60	    delete contextmenu;
61	    delete cursorLabel;
62	}
63	
64	void TracePlot::setParentTile(TileWidget *tile)
65	{
66	    parentTile = tile;
67	    updateContextMenu();
68	}
69	
70	void TracePlot::enableTrace(Trace *t, bool enabled)
71	{
72	    if(traces[t] != enabled) {
73	        traces[t] = enabled;
74	        if(enabled) {
75	            // connect signals
76	            connect(t, &Trace::dataChanged, this, &TracePlot::triggerReplot);
77	            connect(t, &Trace::visibilityChanged, this, &TracePlot::triggerReplot);
78	            connect(t, &Trace::markerFormatChanged, this, &TracePlot::triggerReplot);
79	            connect(t, &Trace::markerAdded, this, &TracePlot::markerAdded);
80	            connect(t, &Trace::markerRemoved, this, &TracePlot::markerRemoved);
81	            connect(t, &Trace::typeChanged, this, &TracePlot::checkIfStillSupported);
82	            connect(t, &Trace::deembeddingChanged, this, &TracePlot::checkIfStillSupported);
83	            connect(t, &Trace::colorChanged, this, &TracePlot::triggerReplot);
84	        } else {
85	            // disconnect from notifications
86	            disconnect(t, &Trace::dataChanged, this, &TracePlot::triggerReplot);
87	            disconnect(t, &Trace::visibilityChanged, this, &TracePlot::triggerReplot);
88	            disconnect(t, &Trace::markerFormatChanged, this, &TracePlot::triggerReplot);
89	            disconnect(t, &Trace::markerAdded, this, &TracePlot::markerAdded);
90	            disconnect(t, &Trace::markerRemoved, this, &TracePlot::markerRemoved);
91	            disconnect(t, &Trace::typeChanged, this, &TracePlot::checkIfStillSupported);
92	            disconnect(t, &Trace::deembeddingChanged, this, &TracePlot::checkIfStillSupported);
93	            disconnect(t, &Trace::colorChanged, this, &TracePlot::triggerReplot);
94	        }
95	        updateContextMenu();
96	        replot();
97	    }
98	}
99	
100	void TracePlot::mouseDoubleClickEvent(QMouseEvent *) {
101	    emit doubleClicked(this);
102	}
103	
104	void TracePlot::updateSpan(double min, double max)
105	{
106	    sweep_fmin = min;
107	    sweep_fmax = max;
108	    triggerReplot();
109	}
110	
111	QString TracePlot::TypeToString(Type t)
112	{
113	    switch(t) {
114	    case Type::EyeDiagram: return "Eye Diagram";
115	    case Type::PolarChart: return "Polar Chart";
116	    case Type::SmithChart: return "Smith Chart";
117	    case Type::Waterfall: return "Waterfall";
118	    case Type::XYPlot: return "XY Plot";
119	    default: return "Invalid";
120	    }
121	}
122	
123	TracePlot::Type TracePlot::TypeFromString(QString s)
124	{
125	    for(unsigned int i=0;i<=(int) Type::EyeDiagram;i++) {
126	        if(TypeToString((Type) i) == s) {
127	            return (Type) i;
128	        }
129	    }
130	    // use default
131	    return Type::XYPlot;
132	}
133	
134	TracePlot *TracePlot::createFromType(TraceModel &model, Type t)
135	{
136	    switch(t) {
137	    case Type::EyeDiagram: return new EyeDiagramPlot(model);
138	    case Type::PolarChart: return new TracePolarChart(model);
139	    case Type::SmithChart: return new TraceSmithChart(model);
140	    case Type::Waterfall: return new TraceWaterfall(model);
141	    case Type::XYPlot: return new TraceXYPlot(model);
142	    default:
143	        return nullptr;
144	    }
145	}
146	
147	void TracePlot::initializeTraceInfo()
148	{
149	    // Populate already present traces
150	    auto tvect = model.getTraces();
151	    for(auto t : tvect) {
152	        newTraceAvailable(t);
153	    }
154	
155	    // connect notification of traces added at later point
156	    connect(&model, &TraceModel::traceAdded, this, &TracePlot::newTraceAvailable);
157	}
158	
159	std::vector<Trace *> TracePlot::activeTraces()
160	{
161	    std::vector<Trace*> ret;
162	    for(auto t : traces) {
163	        if(t.second) {
164	            ret.push_back(t.first);
165	        }
166	    }
167	    return ret;
168	}
169	
170	std::vector<Trace *> TracePlot::orderedTraces()
171	{
172	    std::vector<Trace*> ordered;
173	    for(auto t : traces) {
174	        ordered.push_back(t.first);
175	    }
176	    sort(ordered.begin(), ordered.end(), [](Trace *l, Trace *r) -> bool {
177	        return l->name() < r->name();
178	    });
179	    return ordered;
180	}
181	
182	void TracePlot::contextMenuEvent(QContextMenuEvent *event)
183	{
184	    auto position = event->pos() - QPoint(marginLeft, marginTop);
185	    auto m = markerAtPosition(position);
186	    QMenu *menu;
187	    if(m) {
188	        // right click on marker, execute its contextmenu
189	        menu = m->getContextMenu();
190	    } else {
191	        // no marker, contextmenu of graph
192	        menu = contextmenu;
193	        contextmenuClickpoint = event->pos();
194	    }
195	    menu->exec(event->globalPos());
196	    if(markedForDeletion) {
197	        emit deleted(this);
198	        delete this;
199	    }
200	}
201	
202	void TracePlot::paintEvent(QPaintEvent *event)
203	{
204	    if(traceRemovalPending) {
205	        for(auto t : traces) {
206	            if(!t.second) {
207	                // trace already disabled
208	            }
209	            if(!supported(t.first)) {
210	                enableTrace(t.first, false);
211	            }
212	        }
213	        traceRemovalPending = false;
214	    }
215	
216	    xSweep = std::numeric_limits<double>::quiet_NaN();
217	    for(auto t : traces) {
218	        if(!t.second) {
219	            continue;
220	        }
221	        Trace* tr = t.first;
222	        if(tr->getSource() == Trace::Source::Live && tr->isVisible() && !tr->isPaused()) {
223	            xSweep = model.getSweepPosition();
224	            break;
225	        }
226	    }
227	
228	    Q_UNUSED(event)
229	    auto& pref = Preferences::getInstance();
230	    QPainter p(this);
231	//    p.setRenderHint(QPainter::Antialiasing);
232	    // fill background
233	    p.setBackground(QBrush(pref.Graphs.Color.background));
234	    p.fillRect(0, 0, width(), height(), QBrush(pref.Graphs.Color.background));
235	
236	    marginTop = 0;
237	    // draw title
238	    if(!title.isEmpty()) {
239	        QFont font = p.font();
240	        font.setPixelSize(pref.Graphs.fontSizeTitle);
241	        p.setFont(font);
242	        p.setPen(Util::getFontColorFromBackground(pref.Graphs.Color.background));
243	        p.drawText(QRect(0, 0, width(), pref.Graphs.fontSizeTitle), Qt::AlignCenter, title);
244	        marginTop += pref.Graphs.fontSizeTitle;
245	    }
246	
247	    // show names of active traces and marker data (if enabled)
248	    bool hasMarkerData = false;
249	    auto marginMarkerData = pref.Graphs.fontSizeMarkerData * 12.5;
250	    auto traceNameTop = marginTop + 5;
251	    marginTop += pref.Graphs.fontSizeTraceNames + 8;
252	    int x = 1; // xcoordinate for the next trace name
253	    int y = marginTop; // ycoordinate for the next marker data
254	    auto labelMarginRight = 4;
255	    auto borderRadius = 5;
256	    for(auto t : traces) {
257	        if(!t.second || !t.first->isVisible()) {
258	            continue;
259	        }
260	
261	        // Trace name
262	        auto textArea = QRect(x, traceNameTop, width() - x, pref.Graphs.fontSizeTraceNames + 8);
263	        QFont font = p.font();
264	        font.setPixelSize(pref.Graphs.fontSizeTraceNames);
265	        p.setFont(font);
266	        p.setPen(t.first->color());
267	        auto space = " ";
268	        auto label = space + t.first->name() + space;
269	        QRectF usedLabelArea = p.boundingRect(textArea, 0, label);
270	        QPainterPath path;
271	        path.addRoundedRect(usedLabelArea, borderRadius, borderRadius);
272	        p.fillPath(path, t.first->color());
273	        p.drawPath(path);
274	        p.setPen(Util::getFontColorFromBackground(t.first->color()));
275	        p.drawText(textArea, 0, label);
276	        p.setPen(t.first->color());
277	        x += usedLabelArea.width()+labelMarginRight;
278	
279	        auto tmarkers = t.first->getMarkers();
280	        std::vector<Marker*> vmarkers(tmarkers.begin(), tmarkers.end());
281	        sort(vmarkers.begin(), vmarkers.end(), [](Marker *l, Marker *r) -> bool {
282	            switch(Preferences::getInstance().Marker.sortOrder) {
283	            case PrefMarkerSortXCoord:
284	                return l->getPosition() < r->getPosition();
285	            case PrefMarkerSortNumber:
286	                return l->getNumber() < r->getNumber();
287	            case PrefMarkerSortTimestamp:
288	                return l->getCreationTimestamp() < r->getCreationTimestamp();
289	            }
290	            return false;
291	        });
292	        for(auto m : vmarkers) {
293	            if(!m->isVisible()) {
294	                continue;
295	            }
296	            if(!markerVisible(m->getPosition())) {
297	                // marker not visible with current plot settings
298	                continue;
299	            }
300	            if(m->getGraphDisplayFormats().size() == 0) {
301	                // this marker has nothing to display
302	                continue;
303	            }
304	            hasMarkerData = true;
305	            QFont font = p.font();
306	            font.setPixelSize(pref.Graphs.fontSizeMarkerData);
307	            p.setFont(font);
308	
309	            // Rounded box
310	            auto space = "  ";
311	            auto textArea = QRect(width() - marginRight - marginMarkerData, y, width() - marginRight, y + 100);
312	            auto label = space + QString::number(m->getNumber()) + space;
313	            QRectF textAreaConsumed = p.boundingRect(textArea, 0, label);
314	            QPainterPath pathM;
315	            pathM.addRoundedRect(textAreaConsumed, borderRadius, borderRadius);
316	            p.fillPath(pathM, t.first->color());
317	            p.drawPath(pathM);
318	
319	            // Over box
320	            p.setPen(Util::getFontColorFromBackground(t.first->color()));
321	            p.drawText(textArea, 0, label);
322	
323	            // Non-rounded description
324	            auto description = m->getSuffix() + space + m->readablePosition();
325	            p.setPen(t.first->color());
326	            p.drawText(width() - marginRight - marginMarkerData + textAreaConsumed.width() + 5, textAreaConsumed.y(), width() - marginRight, textArea.height(), 0, description);
327	            y += textAreaConsumed.height();
328	
329	            for(auto f : m->getGraphDisplayFormats()) {
330	                auto textArea = QRect(width() - marginRight - marginMarkerData, y, width() - marginRight, y + 100);
331	                p.drawText(textArea, 0, m->readableData(f), &textAreaConsumed);
332	                y += textAreaConsumed.height();
333	            }
334	            // leave one row empty between markers
335	            y += textAreaConsumed.height();
336	        }
337	    }
338	
339	    unsigned int l = marginLeft;
340	    unsigned int t = marginTop;
341	    unsigned int w = width() - marginLeft - marginRight;
342	    unsigned int h = height() - marginTop - marginBottom;
343	
344	    if(hasMarkerData) {
345	        w -= marginMarkerData;
346	    }
347	
348	    p.setViewport(l, t, w, h);
349	    p.setWindow(0, 0, w, h);
350	
351	    draw(p);
352	
353	    if(dropPending) {
354	        p.setOpacity(dropOpacity);
355	        p.setBrush(dropBackgroundColor);
356	        p.setPen(dropForegroundColor);
357	
358	        auto dropRect = getDropRect();
359	
360	        p.fillRect(0, 0, dropRect.left(), h-1, p.brush());
361	        p.fillRect(dropRect.left(), 0, dropRect.width()-1, dropRect.top(), p.brush());
362	        p.fillRect(dropRect.left(), dropRect.bottom(), dropRect.width()-1, h-1, p.brush());
363	        p.fillRect(dropRect.right(), 0, w-1, h-1, p.brush());
364	
365	        p.setOpacity(1.0);
366	        p.drawLine(QPoint(0, 0), dropRect.topLeft());
367	        p.drawLine(QPoint(0, h-1), dropRect.bottomLeft());
368	        p.drawLine(QPoint(w-1, 0), dropRect.topRight());
369	        p.drawLine(QPoint(w-1, h-1), dropRect.bottomRight());
370	        p.drawLine(QPoint(0, 0), QPoint(0, h-1));
371	        p.drawLine(QPoint(0, h-1), QPoint(w-1, h-1));
372	        p.drawLine(QPoint(w-1, h-1), QPoint(w-1, 0));
373	        p.drawLine(QPoint(w-1, 0), QPoint(0, 0));
374	        p.drawLine(dropRect.topLeft(), dropRect.topRight());
375	        p.drawLine(dropRect.topRight(), dropRect.bottomRight());
376	        p.drawLine(dropRect.bottomRight(), dropRect.bottomLeft());
377	        p.drawLine(dropRect.bottomLeft(), dropRect.topLeft());
378	
379	        auto font = p.font();
380	        font.setPixelSize(20);
381	        p.setFont(font);
382	        p.setPen(dropSection == DropSection::Above ? dropHighlightColor : dropForegroundColor);
383	        p.drawText(QRect(0, 0, w, dropRect.top()), Qt::AlignCenter, "Insert above");
384	        p.setPen(dropSection == DropSection::Below ? dropHighlightColor : dropForegroundColor);
385	        p.drawText(QRect(0, dropRect.bottom(), w, dropRect.top()), Qt::AlignCenter, "Insert below");
386	        p.setPen(dropSection == DropSection::ToTheLeft ? dropHighlightColor : dropForegroundColor);
387	        p.drawText(QRect(0, 0, dropRect.left(), h), Qt::AlignCenter, "Insert to\nthe left");
388	        p.setPen(dropSection == DropSection::ToTheRight ? dropHighlightColor : dropForegroundColor);
389	        p.drawText(QRect(dropRect.right(), 0, dropRect.left(), h), Qt::AlignCenter, "Insert to\nthe right");
390	    }
391	
392	    replotTimer.start(MaxUpdateInterval);
393	}
