541	Marker *TracePlot::markerAtPosition(QPoint p, bool onlyMovable)
542	{
543	    // check if click was near a marker
544	    unsigned int closestDistance = numeric_limits<unsigned int>::max();
545	    Marker *closestMarker = nullptr;
546	    for(auto t : traces) {
547	        if(!t.second) {
548	            // this trace is disabled, skip
549	            continue;
550	        }
551	        auto markers = t.first->getMarkers();
552	        for(Marker* m : markers) {
553	            if(!m->isVisible()) {
554	                // can not interact with invisible markers, pretend that there is nothing here
555	                continue;
556	            }
557	            if(!m->isMovable() && onlyMovable) {
558	                continue;
559	            }
560	            auto markerPoint = markerToPixel(m);
561	            if(markerPoint.isNull()) {
562	                // invalid, skip
563	                continue;
564	            }
565	            if(!positionWithinGraphArea(markerPoint) && !Preferences::getInstance().Marker.clipToYAxis) {
566	                // this marker is currently not visible on the graph, do not accept it as a valid choice
567	                continue;
568	            }
569	            auto diff = markerPoint - p;
570	            unsigned int distance = diff.x() * diff.x() + diff.y() * diff.y();
571	            if(distance < closestDistance) {
572	                closestDistance = distance;
573	                closestMarker = m;
574	            }
575	        }
576	    }
577	    if(closestDistance <= 400) {
578	        return closestMarker;
579	    } else {
580	        return nullptr;
581	    }
582	}
