584	void TracePlot::createMarkerAtPosition(QPoint p)
585	{
586	    // transate from point in absolute coordinates to this widget
587	    p -= QPoint(marginLeft, marginTop);
588	
589	    double closestDistance = std::numeric_limits<double>::max();
590	    Trace *trace = nullptr;
591	    double xpos;
592	    for(auto t : traces) {
593	        if(!t.second) {
594	            // trace not enabled, skip
595	            continue;
596	        }
597	        double distance;
598	        auto x = nearestTracePoint(t.first, p, &distance);
599	        if(distance < closestDistance) {
600	            trace = t.first;
601	            xpos = x;
602	            closestDistance = distance;
603	        }
604	    }
605	    if(!trace) {
606	        // failed to find trace (should not happen)
607	        return;
608	    }
609	
610	    auto markerModel = model.getMarkerModel();
611	    auto marker = markerModel->createDefaultMarker();
612	    marker->assignTrace(trace);
613	    marker->setPosition(xpos);
614	    markerModel->addMarker(marker);
615	}
