639	void TracePlot::dragMoveEvent(QDragMoveEvent *event)
640	{
641	    if(!dropPending) {
642	        return;
643	    }
644	    auto dropRect = getDropRect();
645	    auto pos = event->position().toPoint() - QPoint(marginLeft, marginTop);
646	    if(dropRect.contains(pos)) {
647	        dropSection = DropSection::OnPlot;
648	    } else {
649	        // transform to relative coordinates from 0 to 1
650	        auto x = (double) pos.x() / (width() - marginLeft - marginRight);
651	        auto y = (double) pos.y() / (height() - marginTop - marginBottom);
652	        if(y < 0.5) {
653	            if(x < y) {
654	                dropSection = DropSection::ToTheLeft;
655	            } else if(x > (1.0 - y)) {
656	                dropSection = DropSection::ToTheRight;
657	            } else {
658	                dropSection = DropSection::Above;
659	            }
660	        } else {
661	            if(x < (1.0 - y)) {
662	                dropSection = DropSection::ToTheLeft;
663	            } else if(x > y) {
664	                dropSection = DropSection::ToTheRight;
665	            } else {
666	                dropSection = DropSection::Below;
667	            }
668	        }
669	    }
670	    dropPosition = pos;
671	    replot();
672	}
