674	void TracePlot::dropEvent(QDropEvent *event)
675	{
676	    if(dropTrace) {
677	        if(dropSection == DropSection::OnPlot) {
678	            traceDropped(dropTrace, event->position().toPoint() -  - QPoint(marginLeft, marginTop));
679	        } else {
680	            TileWidget *newTile = nullptr;
681	            // parentTile will be modified by the split, save here
682	            TileWidget *oldParent = parentTile;
683	            switch(dropSection) {
684	            case DropSection::Above:
685	                parentTile->splitVertically(true);
686	                newTile = oldParent->Child1();
687	                break;
688	            case DropSection::Below:
689	                parentTile->splitVertically(false);
690	                newTile = oldParent->Child2();
691	                break;
692	            case DropSection::ToTheLeft:
693	                parentTile->splitHorizontally(true);
694	                newTile = oldParent->Child1();
695	                break;
696	            case DropSection::ToTheRight:
697	                parentTile->splitHorizontally(false);
698	                newTile = oldParent->Child2();
699	                break;
700	            case DropSection::OnPlot:
701	                // already handled above
702	                break;
703	            }
704	            TracePlot *graph = createDefaultPlotForTrace(model, dropTrace);
705	            if(!graph->configureForTrace(dropTrace)) {
706	                // can't be used for the configuration the trace is in, fall back to XY-Plot
707	                delete graph;
708	                graph = new TraceXYPlot(model);
709	                graph->configureForTrace(dropTrace);
710	            }
711	            newTile->setPlot(graph);
712	            graph->enableTrace(dropTrace, true);
713	        }
714	    }
715	    dropPending = false;
716	    dropTrace = nullptr;
717	    replot();
718	}
