804	void TracePlot::checkIfStillSupported(Trace *t)
805	{
806	    if(!supported(t)) {
807	        // something with this trace changed and it can no longer be displayed on this graph
808	        // behavior depends on preferences
809	        switch(Preferences::getInstance().Graphs.domainChangeBehavior) {
810	        case GraphDomainChangeBehavior::RemoveChangedTraces:
811	            // simply remove the changed trace
812	            enableTrace(t, false);
813	            break;
814	        case GraphDomainChangeBehavior::AdjustGrahpsIfOnlyTrace:
815	            // remove trace if other traces are present, otherwise try to adjust graph
816	            if(activeTraces().size() > 1) {
817	                enableTrace(t, false);
818	                break;
819	            }
820	            [[fallthrough]];
821	        case GraphDomainChangeBehavior::AdjustGraphs:
822	            // attempt to configure the graph for the changed trace, remove only if this fails
823	            if(!configureForTrace(t)) {
824	                enableTrace(t, false);
825	            } else {
826	                // other trace may need to be removed because the graph no longer supports them. However, they (the traces)
827	                // may change soon as well (e.g. because multiple traces changed at the same time and we are only handling
828	                // the first changed trace right now). Postpone the deletion of other traces until all currently executing
829	                // slots have completed
830	                QTimer::singleShot(0, [this]{
831	                    for(auto t : activeTraces()) {
832	                        if(!supported(t)) {
833	                            enableTrace(t, false);
834	                        }
835	                    }
836	                });
837	            }
838	            break;
839	        }
840	
841	    }
842	}
