72	    } else {
73	        ui->displayModeImp->setCurrentIndex(0);
74	    }
75	
76	    ui->displayStartFreq->setUnit("Hz");
77	    ui->displayStartFreq->setPrefixes(" kMG");
78	    ui->displayStartFreq->setPrecision(6);
79	    ui->displayStartFreq->setValue(fmin);
