87	        ui->displayStartFreq->setEnabled(active);
88	        ui->displayStopFreq->setEnabled(active);
89	    });
90	    ui->displayFreqOverride->setChecked(manualFrequencyRange);
91	    emit ui->displayFreqOverride->toggled(manualFrequencyRange);
92	
93	    ui->zoomReflection->setPrecision(3);
94	    ui->zoomFactor->setPrecision(3);
95	    ui->zoomReflection->setValue(edgeReflection);
96	    ui->zoomFactor->setValue(1.0/edgeReflection);
97	    ui->offsetRealAxis->setPrecision(4);
98	    ui->offsetRealAxis->setValue(offset.x());
99	    ui->offsetImagAxis->setPrecision(4);
100	    ui->offsetImagAxis->setValue(offset.y());
101	
102	    ui->impedance->setUnit("Ω");
103	    ui->impedance->setPrecision(3);
104	    ui->impedance->setValue(Z0);
105	
106	    auto model = new SmithChartContantLineModel(*this);
107	    ui->lineTable->setModel(model);
108	    ui->lineTable->setItemDelegateForColumn(SmithChartContantLineModel::ColIndexType, new SmithChartTypeDelegate);
109	    ui->lineTable->setItemDelegateForColumn(SmithChartContantLineModel::ColIndexParam, new SmithChartParamDelegate);
110	
111	    auto updateSettings = [=]() {
112	        limitToSpan = ui->displayModeFreq->currentIndex() == 1;
113	        limitToEdge = ui->displayModeImp->currentIndex() == 1;
114	        manualFrequencyRange = ui->displayFreqOverride->isChecked();
115	        fmin = ui->displayStartFreq->value();
116	        fmax = ui->displayStopFreq->value();
117	        updateContextMenu();
118	        triggerReplot();
119	    };
120	
121	    connect(ui->buttonBox->button(QDialogButtonBox::Apply), &QPushButton::clicked, [=](){
122	       updateSettings();
123	    });
124	
125	    connect(ui->buttonBox, &QDialogButtonBox::accepted, [=](){
126	       updateSettings();
127	    });
128	    connect(ui->zoomFactor, &SIUnitEdit::valueChanged, [=](){
129	        edgeReflection = 1.0 / ui->zoomFactor->value();
130	        ui->zoomReflection->setValueQuiet(edgeReflection);
131	    });
132	    connect(ui->zoomReflection, &SIUnitEdit::valueChanged, [=](){
133	        edgeReflection = ui->zoomReflection->value();
134	        ui->zoomFactor->setValueQuiet(1.0 / edgeReflection);
135	    });
136	    connect(ui->offsetRealAxis, &SIUnitEdit::valueChanged, [=](){
137	        offset = QPointF(ui->offsetRealAxis->value(), offset.y());
138	    });
139	    connect(ui->offsetImagAxis, &SIUnitEdit::valueChanged, [=](){
140	        offset = QPointF(offset.x(), ui->offsetRealAxis->value());
141	    });
142	    connect(ui->impedance, &SIUnitEdit::valueChanged, [=](){
143	        Z0 = ui->impedance->value();
144	        for(auto t : traces) {
145	            if(t.second) {
146	                checkIfStillSupported(t.first);
147	            }
148	        }
149	        // depending on the preferences, the Z0 value may have been changed to match the active traces,
150	        // overwrite again without causing an additional signal
151	        ui->impedance->setValueQuiet(Z0);
152	    });
153	    connect(ui->lineTable, &QTableView::clicked, [=](const QModelIndex &index){
154	        if(index.column() == SmithChartContantLineModel::ColIndexColor) {
155	            auto line = &constantLines[index.row()];
156	            auto newColor = QColorDialog::getColor(line->getColor(), parentWidget(), "Select color", QColorDialog::DontUseNativeDialog);
157	            if(newColor.isValid()) {
158	                line->setColor(newColor);
159	                emit model->dataChanged(index, index);
160	                triggerReplot();
161	            }
162	        }
