238	void TraceSmithChart::draw(QPainter &p) {
239	    auto& pref = Preferences::getInstance();
240	
241	    // translate coordinate system so that the smith chart sits in the origin and has a size of 1
242	    auto w = p.window();
243	    p.save();
244	    p.translate(w.width()/2, w.height()/2);
245	    auto scale = qMin(w.height(), w.width()) / (2.0 * polarCoordMax);
246	    p.scale(scale, scale);
247	
248	    transform = p.transform();
249	    p.restore();
250	
251	    auto drawArc = [&](SmithChartArc a) {
252	        a.constrainToCircle(QPointF(0,0), edgeReflection);
253	        auto topleft = dataToPixel(complex<double>(a.center.x() - a.radius, a.center.y() - a.radius));
254	        auto bottomright = dataToPixel(complex<double>(a.center.x() + a.radius, a.center.y() + a.radius));
255	        a.startAngle *= 5760 / (2*M_PI);
256	        a.spanAngle *= 5760 / (2*M_PI);
257	        p.drawArc(QRect(topleft, bottomright), a.startAngle, a.spanAngle);
258	    };
259	
260	    // Outer circle
261	    auto pen = QPen(pref.Graphs.Color.axis);
262	    pen.setCosmetic(true);
263	    p.setPen(pen);
264	    drawArc(SmithChartArc(QPointF(0, 0), edgeReflection, 0, 2*M_PI));
265	
266	    constexpr int Circles = 6;
267	    pen = QPen(pref.Graphs.Color.Ticks.divisions, 0.5, Qt::DashLine);
268	    pen.setCosmetic(true);
269	    p.setPen(pen);
270	    for(int i=1;i<Circles * 2;i++) {
271	        auto radius = (double) i / Circles;
272	        drawArc(SmithChartArc(QPointF(1.0 - radius+offset.x(), 0.0+offset.y()), radius, 0, 2*M_PI));
273	        drawArc(SmithChartArc(QPointF(1.0 + radius+offset.x(), 0.0+offset.y()), radius, 0, 2*M_PI));
274	    }
275	
276	    QPointF p1 = QPointF(-100, offset.y());
277	    QPointF p2 = QPointF(100, offset.y());
278	    if(TracePolar::constrainLineToCircle(p1, p2, QPointF(0,0), edgeReflection)) {
279	        // center line visible
280	        p.drawLine(dataToPixel(p1),dataToPixel(p2));
281	    }
282	    const std::array<double, 5> impedanceLines = {Z0*0.2, Z0*0.5, Z0, Z0*2, Z0*5};
283	    for(auto z : impedanceLines) {
284	        z /= Z0;
285	        auto radius = 1.0/z;
286	        drawArc(SmithChartArc(QPointF(1.0+offset.x(), radius+offset.y()), radius, 0, 2*M_PI));
287	        drawArc(SmithChartArc(QPointF(1.0+offset.x(), -radius+offset.y()), radius, 0, 2*M_PI));
288	    }
289	
290	    // draw custom constant parameter lines
291	    for(auto line : constantLines) {
292	        pen = QPen(line.getColor(), pref.Graphs.lineWidth);
293	        pen.setCosmetic(true);
294	        p.setPen(pen);
295	        for(auto arc : line.getArcs(Z0)) {
296	            arc.center += offset;
297	            drawArc(arc);
298	        }
299	    }
300	
301	    for(auto t : traces) {
302	        if(!t.second) {
303	            // trace not enabled in plot
304	            continue;
305	        }
306	        auto trace = t.first;
307	        if(!trace->isVisible()) {
308	            // trace marked invisible
309	            continue;
310	        }
311	        pen = QPen(trace->color(), pref.Graphs.lineWidth);
312	        pen.setCosmetic(true);
313	        p.setPen(pen);
314	        int nPoints = trace->size();
315	        for(int i=1;i<nPoints;i++) {
316	            auto last = trace->sample(i-1);
317	            auto now = trace->sample(i);
318	            if ((trace->outputType() == Trace::DataType::Frequency) && (last.x < minimumVisibleFrequency() || now.x > maximumVisibleFrequency())) {
319	                continue;
320	            }
321	            if(isnan(now.y.real())) {
322	                break;
323	            }
324	
325	            if(pref.Graphs.SweepIndicator.hide && !isnan(xSweep) && trace->getSource() == Trace::Source::Live && trace->isVisible() && !trace->isPaused()) {
326	                // check if this part of the trace is visible
327	                double range = maximumVisibleFrequency() - minimumVisibleFrequency();
328	                double afterSweep = now.x - xSweep;
329	                if(afterSweep > 0 && afterSweep * 100 / range <= pref.Graphs.SweepIndicator.hidePercent) {
330	                    // do not display this part of the trace
331	                    continue;
332	                }
333	            }
334	
335	            last = dataAddOffset(last);
336	            now = dataAddOffset(now);
337	
338	            // scale to size of smith diagram
339	            QPointF p1 = dataToPixel(last);
340	            QPointF p2 = dataToPixel(now);
341	
342	            if(limitToEdge && (abs(last.y) > edgeReflection || abs(now.y) > edgeReflection)) {
343	                // partially outside of visible area, constrain
344	                if(!TracePolar::constrainLineToCircle(p1, p2, transform.map(QPointF(0,0)), polarCoordMax * scale)) {
345	                    // completely out of visible area
346	                    continue;
347	                }
348	            }
349	
350	            // draw line
351	            p.drawLine(p1, p2);
352	        }
353	        if(trace->size() > 0) {
354	            // only draw markers if the trace has at least one point
355	            auto markers = t.first->getMarkers();
356	            for(auto m : markers) {
357	                if(!m->isVisible()) {
358	                    continue;
359	                }
360	//                if (m->isTimeDomain()) {
361	//                    continue;
362	//                }
363	                if (m->getPosition() < minimumVisibleFrequency() || m->getPosition() > maximumVisibleFrequency()) {
364	                    continue;
365	                }
366	                if(m->getPosition() < trace->minX() || m->getPosition() > trace->maxX()) {
367	                    // marker not in trace range
368	                    continue;
369	                }
370	                auto point = markerToPixel(m);
371	                if(point.isNull()) {
372	                    // marker point is invalid
373	                    continue;
374	                }
375	
376	                // if (limitToEdge && abs(pixelToData(point)) > edgeReflection) {
377	                //     // outside of visible area
378	                //     continue;
379	                // }
380	                auto symbol = m->getSymbol();
381	                p.drawPixmap(point.x() - symbol.width()/2, point.y() - symbol.height(), symbol);
382	            }
383	        }
384	    }
385	    if(dropPending && supported(dropTrace)) {
386	        // adjust coords due to shifted restore
387	        p.setOpacity(dropOpacity);
388	        p.setBrush(dropBackgroundColor);
389	        p.setPen(dropForegroundColor);
390	        p.drawRect(getDropRect());
391	        auto font = p.font();
392	        font.setPixelSize(20);
393	        p.setFont(font);
394	        p.setOpacity(1.0);
395	        p.setPen(dropSection == DropSection::OnPlot ? dropHighlightColor : dropForegroundColor);
396	        auto text = "Drop here to add\n" + dropTrace->name() + "\nto Smith chart";
397	        p.drawText(p.window(), Qt::AlignCenter, text);
398	    }
399	}
400	
401	void TraceSmithChart::traceDropped(Trace *t, QPoint position)
402	{
403	    if(!supported(t) && dropSupported(t)) {
404	        // needs to switch to a different domain for the graph
405	        if(!InformationBox::AskQuestion("Reference impedance change", "You dropped a trace that is not supported with the currently selected reference impedance."
406	                                    " Do you want to remove all traces and change the graph to the correct reference imppedance?", true, "ReferenceImpedanceChangeRequest")) {
407	            // user declined to change domain, to not add change impedance
408	            return;
409	        }
410	        // attempt to configure for this trace
411	        configureForTrace(t);
412	    }
413	    TracePlot::traceDropped(t, position);
414	}
415	
416	bool TraceSmithChart::dropSupported(Trace *t)
417	{
418	    if(!t->isReflection()) {
419	        return false;
420	    }
