485	void SmithChartArc::constrainToCircle(QPointF center, double radius)
486	{
487	    // check if arc/circle intersect
488	    auto centerDiff = this->center - center;
489	    auto centerDistSquared = centerDiff.x() * centerDiff.x() + centerDiff.y() * centerDiff.y();
490	    if (centerDistSquared >= (radius + this->radius) * (radius + this->radius)) {
491	        // arc completely outside of constraining circle
492	        spanAngle = 0.0;
493	        return;
494	    } else if (centerDistSquared <= (radius - this->radius) * (radius - this->radius)) {
495	        if (radius >= this->radius) {
496	            // arc completely in constraining circle, do nothing
497	            return;
498	        } else {
499	            // arc completely outside of circle
500	            spanAngle = 0.0;
501	            return;
502	        }
503	    } else {
504	        // there are intersections between the arc and the circle. Calculate points according to https://stackoverflow.com/questions/3349125/circle-circle-intersection-points
505	        auto distance = sqrt(centerDistSquared);
506	        auto a = (this->radius*this->radius-radius*radius+distance*distance) / (2*distance);
507	        auto h = sqrt(this->radius*this->radius - a*a);
508	        auto intersectMiddle = this->center + a*(center - this->center) / distance;
509	        auto rotatedCenterDiff = center - this->center;
510	        swap(rotatedCenterDiff.rx(), rotatedCenterDiff.ry());
511	        rotatedCenterDiff.setY(-rotatedCenterDiff.y());
512	        auto intersect1 = intersectMiddle + h * rotatedCenterDiff / distance;
513	        auto intersect2 = intersectMiddle - h * rotatedCenterDiff / distance;
514	
515	        // got intersection points, convert into angles from arc center
516	        auto wrapAngle = [](double angle) -> double {
517	            double ret = fmod(angle, 2*M_PI);
518	            if(ret < 0) {
519	                ret += 2*M_PI;
520	            }
521	            return ret;
522	        };
523	
524	        auto angle1 = wrapAngle(atan2((intersect1 - this->center).y(), (intersect1 - this->center).x()));
525	        auto angle2 = wrapAngle(atan2((intersect2 - this->center).y(), (intersect2 - this->center).x()));
526	
527	        auto angleDiff = wrapAngle(angle2 - angle1);
528	        if ((angleDiff >= M_PI) ^ (a > 0.0)) {
529	            // allowed angles go from intersect1 to intersect2
530	            if(startAngle < angle1) {
531	                startAngle = angle1;
532	            }
533	            auto maxSpan = wrapAngle(angle2 - startAngle);
534	            if(spanAngle > maxSpan) {
535	                spanAngle = maxSpan;
536	            }
537	        } else {
538	            // allowed angles go from intersect2 to intersect1
539	            if(startAngle < angle2) {
540	                startAngle = angle2;
541	            }
542	            auto maxSpan = wrapAngle(angle1 - startAngle);
543	            if(spanAngle > maxSpan) {
544	                spanAngle = maxSpan;
545	            }
546	        }
547	    }
548	}
