557	std::vector<SmithChartArc> SmithChartConstantLine::getArcs(double Z0)
558	{
559	    std::vector<SmithChartArc> arcs;
560	    switch(type) {
561	    case Type::VSWR:
562	        arcs.push_back(SmithChartArc(QPointF(0.0, 0.0), (param - 1.0) / (param + 1.0)));
563	        break;
564	    case Type::Resistance: {
565	        auto circleLeft = (param / Z0 - 1.0) / (param / Z0 + 1.0);
566	        arcs.push_back(SmithChartArc(QPointF((circleLeft + 1.0) / 2, 0.0), (1.0 - circleLeft) / 2.0));
567	    }
568	        break;
569	    case Type::Reactance: {
570	        auto radius = 1.0/(param / Z0);
571	        if(radius > 0) {
572	            arcs.push_back(SmithChartArc(QPointF(1.0, radius), radius));
573	        } else {
574	            arcs.push_back(SmithChartArc(QPointF(1.0, radius), -radius));
575	        }
576	    }
577	        break;
578	    case Type::Q: {
579	        auto center = 1.0 / param;
580	        auto radius = sqrt(center*center + 1.0);
581	        arcs.push_back(SmithChartArc(QPointF(0.0, center), radius));
582	        arcs.push_back(SmithChartArc(QPointF(0.0, -center), radius));
583	    }
584	        break;
585	    case Type::Last:
586	        break;
587	    }
588	    return arcs;
589	}
