187	double TracePolar::nearestTracePoint(Trace *t, QPoint pixel, double *distance)
188	{
189	    double closestDistance = numeric_limits<double>::max();
190	    double closestXpos = 0;
191	    unsigned int closestIndex = 0;
192	    auto samples = t->size();
193	    for(unsigned int i=0;i<samples;i++) {
194	        auto data = t->sample(i);
195	        if(data.x < minimumVisibleFrequency() || data.x > maximumVisibleFrequency()) {
196	            // outside of displayed range
197	            continue;
198	        }
199	        data = dataAddOffset(data);
200	        if(limitToEdge && abs(data.y) > edgeReflection) {
201	            // this trace point is outside of the visible range, clip to circle
202	            data.y /= (abs(data.y) / edgeReflection);
203	        }
204	        auto plotPoint = dataToPixel(data);
205	        if (plotPoint.isNull()) {
206	            // destination point outside of currently displayed range
207	            continue;
208	        }
209	        auto diff = plotPoint - pixel;
210	        unsigned int distance = diff.x() * diff.x() + diff.y() * diff.y();
211	        if(distance < closestDistance) {
212	            closestDistance = distance;
213	            closestXpos = t->sample(i).x;
214	            closestIndex = i;
215	        }
216	    }
217	    closestDistance = sqrt(closestDistance);
218	
219	    if(closestIndex > 0 && t->sample(closestIndex-1).x >= minimumVisibleFrequency()) {
220	        auto l1 = dataToPixel(dataAddOffset(t->sample(closestIndex-1)));
221	        auto l2 = dataToPixel(dataAddOffset(t->sample(closestIndex)));
222	        double ratio;
223	        auto distance = Util::distanceToLine(pixel, l1, l2, nullptr, &ratio);
224	        if(distance < closestDistance) {
225	            closestDistance = distance;
226	            closestXpos = t->sample(closestIndex-1).x + (t->sample(closestIndex).x - t->sample(closestIndex-1).x) * ratio;
227	        }
228	    }
229	    if(closestIndex < t->size() - 1 && t->sample(closestIndex+1).x <= maximumVisibleFrequency()) {
230	        auto l1 = dataToPixel(dataAddOffset(t->sample(closestIndex)));
231	        auto l2 = dataToPixel(dataAddOffset(t->sample(closestIndex+1)));
232	        double ratio;
233	        auto distance = Util::distanceToLine(pixel, l1, l2, nullptr, &ratio);
234	        if(distance < closestDistance) {
235	            closestDistance = distance;
236	            closestXpos = t->sample(closestIndex).x + (t->sample(closestIndex+1).x - t->sample(closestIndex).x) * ratio;
237	        }
238	    }
239	    if(distance) {
240	        *distance = closestDistance;
241	    }
242	    return closestXpos;
243	}
