330	bool TracePolar::constrainLineToCircle(QPointF &a, QPointF &b, QPointF center, double radius)
331	{
332	    auto distance = [](const QPointF &a, const QPointF &b) {
333	        auto dx = b.x() - a.x();
334	        auto dy = b.y() - a.y();
335	        return sqrt(dx*dx + dy*dy);
336	    };
337	
338	    if(distance(a, center) <= radius && distance(b, center) <= radius) {
339	        // both points are completely contained within the circle, no adjustment necessary
340	        return true;
341	    }
342	
343	    // shift points, the formulas assume center = (0,0)
344	    a -= center;
345	    b -= center;
346	
347	    // according to https://mathworld.wolfram.com/Circle-LineIntersection.html
348	    auto dx = b.x() - a.x();
349	    auto dy = b.y() - a.y();
350	    auto dr = sqrt(dx*dx+dy*dy);
351	    auto D = a.x()*b.y() - b.x()*a.y();
352	    // check intersection
353	    auto delta = radius*radius * dr*dr - D*D;
354	    if(delta <= 0) {
355	        // line does not intersect the circle
356	        return false;
357	    }
358	    // line intersects the circle, calculate intersection points
359	    auto x1 = (D*dy+copysign(1.0, dy) * dx*sqrt(delta)) / (dr*dr);
360	    auto x2 = (D*dy-copysign(1.0, dy) * dx*sqrt(delta)) / (dr*dr);
361	    auto y1 = (-D*dx+abs(dy)*sqrt(delta)) / (dr*dr);
362	    auto y2 = (-D*dx-abs(dy)*sqrt(delta)) / (dr*dr);
363	
364	    auto inter1 = QPointF(x1, y1);
365	    auto inter2 = QPointF(x2, y2);
366	
367	    bool inter1betweenPoints = false;
368	    bool inter2betweenPoints = false;
369	    if(abs(distance(a, inter1) + distance(b, inter1) - distance(a, b)) < 0.000001) {
370	        inter1betweenPoints = true;
371	    }
372	    if(abs(distance(a, inter2) + distance(b, inter2) - distance(a, b)) < 0.000001) {
373	        inter2betweenPoints = true;
374	    }
375	    if(inter1betweenPoints && inter2betweenPoints) {
376	        // adjust both points, order does not matter
377	        a = inter1;
378	        b = inter2;
379	    } else if(!inter1betweenPoints && !inter2betweenPoints) {
380	        // the line intersect the circle but outside of the segment defined by the points -> ignore
381	        a += center;
382	        b += center;
383	        return false;
384	    } else {
385	        // exactly one intersection point must lie between the two line points, otherwise we would have returned already
386	        auto inter = inter1betweenPoints ? inter1 : inter2;
387	        if(distance(a, QPointF(0,0)) < radius) {
388	            // point is in the circle and can remain unchanged. Use inter as new point b
389	            b = inter;
390	        } else {
391	            // the other way around
392	            a = inter;
393	        }
394	    }
395	    a += center;
396	    b += center;
397	    return true;
398	}
