409	void PolarArc::constrainToCircle(QPointF center, double radius)
410	{
411	    // check if arc/circle intersect
412	    auto centerDiff = this->center - center;
413	    auto centerDistSquared = centerDiff.x() * centerDiff.x() + centerDiff.y() * centerDiff.y();
414	    if (centerDistSquared >= (radius + this->radius) * (radius + this->radius)) {
415	        // arc completely outside of constraining circle
416	        spanAngle = 0.0;
417	        return;
418	    } else if (centerDistSquared <= (radius - this->radius) * (radius - this->radius)) {
419	        if (radius >= this->radius) {
420	            // arc completely in constraining circle, do nothing
421	            return;
422	        } else {
423	            // arc completely outside of circle
424	            spanAngle = 0.0;
425	            return;
426	        }
427	    } else {
428	        // there are intersections between the arc and the circle. Calculate points according to https://stackoverflow.com/questions/3349125/circle-circle-intersection-points
429	        auto distance = sqrt(centerDistSquared);
430	        auto a = (this->radius*this->radius-radius*radius+distance*distance) / (2*distance);
431	        auto h = sqrt(this->radius*this->radius - a*a);
432	        auto intersectMiddle = this->center + a*(center - this->center) / distance;
433	        auto rotatedCenterDiff = center - this->center;
434	        swap(rotatedCenterDiff.rx(), rotatedCenterDiff.ry());
435	        rotatedCenterDiff.setY(-rotatedCenterDiff.y());
436	        auto intersect1 = intersectMiddle + h * rotatedCenterDiff / distance;
437	        auto intersect2 = intersectMiddle - h * rotatedCenterDiff / distance;
438	
439	        // got intersection points, convert into angles from arc center
440	        auto wrapAngle = [](double angle) -> double {
441	            double ret = fmod(angle, 2*M_PI);
442	            if(ret < 0) {
443	                ret += 2*M_PI;
444	            }
445	            return ret;
446	        };
447	
448	        auto angle1 = wrapAngle(atan2((intersect1 - this->center).y(), (intersect1 - this->center).x()));
449	        auto angle2 = wrapAngle(atan2((intersect2 - this->center).y(), (intersect2 - this->center).x()));
450	
451	        auto angleDiff = wrapAngle(angle2 - angle1);
452	        if ((angleDiff >= M_PI) ^ (a > 0.0)) {
453	            // allowed angles go from intersect1 to intersect2
454	            if(startAngle < angle1) {
455	                startAngle = angle1;
456	            }
457	            auto maxSpan = wrapAngle(angle2 - startAngle);
458	            if(spanAngle > maxSpan) {
459	                spanAngle = maxSpan;
460	            }
461	        } else {
462	            // allowed angles go from intersect2 to intersect1
463	            if(startAngle < angle2) {
464	                startAngle = angle2;
465	            }
466	            auto maxSpan = wrapAngle(angle1 - startAngle);
467	            if(spanAngle > maxSpan) {
468	                spanAngle = maxSpan;
469	            }
470	        }
471	    }
472	}
