199	void TraceXYPlot::fromJSON(nlohmann::json j)
200	{
201	    parseBaseJSON(j);
202	    auto jX = j["XAxis"];
203	    // old format used enum value for type and mode, new format uses string encoding (more robust when additional enum values are added).
204	    // Check which format is used and parse accordingly
205	    XAxis::Type xtype;
206	    if(jX["type"].type() == nlohmann::json::value_t::string) {
207	        xtype = XAxis::TypeFromName(QString::fromStdString(jX["type"]));
208	    } else {
209	        xtype = jX.value("type", XAxis::Type::Frequency);
210	    }
211	    XAxisMode xmode;
212	    if(jX["mode"].type() == nlohmann::json::value_t::string) {
213	        xmode = AxisModeFromName(QString::fromStdString(jX["mode"]));
214	    } else {
215	        xmode = jX.value("mode", XAxisMode::UseSpan);
216	    }
217	//    auto xlog = jX.value("log", false);
218	    auto xmin = jX.value("min", 0.0);
219	    auto xmax = jX.value("max", 6000000000.0);
220	    auto xdivs = jX.value("divs", 10);
221	    // older formats specified the spacing instead of the number of divisions
222	    if(jX.contains("div")) {
223	        xdivs = (xmax - xmin) / jX.value("div", 600000000.0);
224	    }
225	    auto xautodivs = jX.value("autoDivs", false);
226	    auto xlog = jX.value("log", false);
227	    setXAxis(xtype, xmode, xlog, xmin, xmax, xdivs, xautodivs);
228	    nlohmann::json jY[2] = {j["YPrimary"], j["YSecondary"]};
229	    for(unsigned int i=0;i<2;i++) {
230	        YAxis::Type ytype;
231	        if(jY[i]["type"].type() == nlohmann::json::value_t::string) {
232	            ytype = YAxis::TypeFromName(QString::fromStdString(jY[i]["type"]));
233	        } else {
234	            ytype = jY[i].value("type", YAxis::Type::Disabled);
235	        }
236	        auto yauto = jY[i].value("autorange", true);
237	        auto ylog = jY[i].value("log", false);
238	        auto ymin = jY[i].value("min", -120.0);
239	        auto ymax = jY[i].value("max", 20.0);
240	        auto ydivs = jY[i].value("divs", 10);
241	        // older formats specified the spacing instead of the number of divisions
242	        if(jY[i].contains("div")) {
243	            ydivs = (ymax - ymin) / jY[i].value("div", 10);
244	        }
245	        auto yautodivs = jY[i].value("autoDivs", false);
246	        setYAxis(i, ytype, ylog, yauto, ymin, ymax, ydivs, yautodivs);
247	        for(unsigned int hash : jY[i]["traces"]) {
248	            // attempt to find the traces with this hash
249	            bool found = false;
250	            for(auto t : model.getTraces()) {
251	                if(t->toHash() == hash) {
252	                    enableTraceAxis(t, i, true);
253	                    found = true;
254	                    break;
255	                }
256	            }
257	            if(!found) {
258	                qWarning() << "Unable to find trace with hash" << hash;
259	            }
260	        }
261	    }
262	    if(j.contains("limitLines")) {
263	        for(auto jline : j["limitLines"]) {
264	            auto line = new XYPlotConstantLine;
265	            line->fromJSON(jline);
266	            constantLines.push_back(line);
267	        }
268	    }
269	}
