303	bool TraceXYPlot::configureForTrace(Trace *t)
304	{
305	    YAxis::Type yLeftDefault = YAxis::Type::Disabled;
306	    YAxis::Type yRightDefault = YAxis::Type::Disabled;
307	
308	    switch(t->outputType()) {
309	    case Trace::DataType::Frequency:
310	        setXAxis(XAxis::Type::Frequency, XAxisMode::FitTraces, false, 0, 1, 10, false);
311	        yLeftDefault = YAxis::Type::Magnitude;
312	        yRightDefault = YAxis::Type::Phase;
313	        break;
314	    case Trace::DataType::Time:
315	        setXAxis(XAxis::Type::Time, XAxisMode::FitTraces, false, 0, 1, 10, false);
316	        yLeftDefault = YAxis::Type::ImpulseMag;
317	        break;
318	    case Trace::DataType::Power:
319	        setXAxis(XAxis::Type::Power, XAxisMode::FitTraces, false, 0, 1, 10, false);
320	        yLeftDefault = YAxis::Type::Magnitude;
321	        yRightDefault = YAxis::Type::Phase;
322	        break;
323	    case Trace::DataType::TimeZeroSpan:
324	        setXAxis(XAxis::Type::TimeZeroSpan, XAxisMode::FitTraces, false, 0, 1, 10, false);
325	        yLeftDefault = YAxis::Type::Magnitude;
326	        yRightDefault = YAxis::Type::Phase;
327	        break;
328	    case Trace::DataType::Invalid:
329	        // unable to add
330	        return false;
331	    }
332	    if(!yAxis[0].isSupported(xAxis.getType(), getModel().getSource())) {
333	        setYAxis(0, yLeftDefault, false, false, YAxis::getDefaultLimitMin(yLeftDefault), YAxis::getDefaultLimitMax(yLeftDefault), 10, true);
334	    }
335	    if(!yAxis[1].isSupported(xAxis.getType(), getModel().getSource())) {
336	        setYAxis(1, yRightDefault, false, false, YAxis::getDefaultLimitMin(yRightDefault), YAxis::getDefaultLimitMax(yRightDefault), 10, true);
337	    }
338	    traceRemovalPending = true;
339	    return true;
340	}
