876	void TraceXYPlot::updateAxisTicks()
877	{
878	    if(xAxisMode != XAxisMode::Manual) {
879	        // automatic mode, figure out limits
880	        double max = std::numeric_limits<double>::lowest();
881	        double min = std::numeric_limits<double>::max();
882	        if(xAxisMode == XAxisMode::UseSpan) {
883	            min = sweep_fmin;
884	            max = sweep_fmax;
885	        } else if(xAxisMode == XAxisMode::FitTraces) {
886	            for(auto t : traces) {
887	                bool enabled = (tracesAxis[0].find(t.first) != tracesAxis[0].end()
888	                        || tracesAxis[1].find(t.first) != tracesAxis[1].end());
889	                auto trace = t.first;
890	                if(enabled && trace->isVisible()) {
891	                    if(!trace->size()) {
892	                        // empty trace, do not use for automatic axis calculation
893	                        continue;
894	                    }
895	                    // this trace is currently displayed
896	                    double trace_min = trace->minX();
897	                    double trace_max = trace->maxX();
898	                    if(xAxis.getType() == XAxis::Type::Distance) {
899	                        trace_min = trace->timeToDistance(trace_min);
900	                        trace_max = trace->timeToDistance(trace_max);
901	                    }
902	                    if(trace_min < min) {
903	                        min = trace_min;
904	                    }
905	                    if(trace_max > max) {
906	                        max = trace_max;
907	                    }
908	                }
909	            }
910	        }
911	        xAxis.set(xAxis.getType(), xAxis.getLog(), true, min, max, 0, xAxis.getAutoDivs());
912	    }
913	
914	    for(int i=0;i<2;i++) {
915	        if(yAxis[i].getAutorange()) {
916	            // automatic mode, figure out limits
917	            double max = std::numeric_limits<double>::lowest();
918	            double min = std::numeric_limits<double>::max();
919	            for(auto t : tracesAxis[i]) {
920	                if(!t->isVisible()) {
921	                    continue;
922	                }
923	                unsigned int samples = t->size();
924	                for(unsigned int j=0;j<samples;j++) {
925	                    auto point = traceToCoordinate(t, j, yAxis[i]);
926	
927	                    if(point.x() < xAxis.getRangeMin() || point.x() > xAxis.getRangeMax()) {
928	                        // this point is not in the displayed X range, skip for auto Y range calculation
929	                        continue;
930	                    }
931	
932	                    if(isnan(point.y()) || isinf(point.y())) {
933	                        // skip NaN and Infty values
934	                        continue;
935	                    }
936	
937	                    if(point.y() > max) {
938	                        max = point.y();
939	                    }
940	                    if(point.y() < min) {
941	                        min = point.y();
942	                    }
943	                }
944	            }
945	            if(max >= min) {
946	                auto range = max - min;
947	                if(yAxis[i].getLog()){
948	                    // log axis
949	
950	                    double maxLog10 = log10(abs(max));
951	                    // prevent zero-crossing
952	                    if(min <= 0.0 && max > 0) {
953	                        min = pow(10, maxLog10 - 3); // just show 3 decades by default
954	                    } else if(min >= 0.0 && max < 0) {
955	                        // same thing if negative
956	                        min = -pow(10, maxLog10 - 3);
957	                    }
958	                    // add 5% visible range
959	                    double ratio = log10(max/min);
960	                    max *= pow(10, ratio * 0.05);
961	                    min /= pow(10, ratio * 0.05);
962	                } else {
963	                    // linear axis
964	                    if(range == 0.0) {
965	                        // this could happen if all values in a trace are identical (e.g. imported ideal touchstone files)
966	                        if(max == 0.0) {
967	                            // simply use +/-1 range
968	                            max = 1.0;
969	                            min = -1.0;
970	                        } else {
971	                            // +/-5% around value
972	                            max += abs(max * 0.05);
973	                            min -= abs(max * 0.05);
974	                        }
975	                    } else {
976	                        // add 5% of range at both ends
977	                        min -= range * 0.05;
978	                        max += range * 0.05;
979	                    }
980	                }
981	            } else {
982	                // max/min still at default values, no valid samples are available for this axis, use default range
983	                if(!yAxis[i].getLog()) {
984	                    // linear axis
985	                    max = 1.0;
986	                    min = -1.0;
987	                } else {
988	                    // log axis
989	                    max = 100.0;
990	                    min = 0.1;
991	                }
992	            }
993	            yAxis[i].set(yAxis[i].getType(), yAxis[i].getLog(), true, min, max, 0, xAxis.getAutoDivs());
994	        }
995	    }
996	}
