1019	void TraceXYPlot::enableTraceAxis(Trace *t, int axis, bool enabled)
1020	{
1021	    if(enabled && !supported(t, yAxis[axis].getType())) {
1022	        // unable to add trace to the requested axis
1023	        return;
1024	    }
1025	    if(enabled) {
1026	        TracePlot::enableTrace(t, true);
1027	    } else {
1028	        // only disable trace on parent trace list if disabled for both axes
1029	        int otherAxis = axis ? 0 : 1;
1030	        if(tracesAxis[otherAxis].find(t) == tracesAxis[otherAxis].end()) {
1031	            TracePlot::enableTrace(t, false);
1032	        }
1033	    }
1034	    bool alreadyEnabled = tracesAxis[axis].find(t) != tracesAxis[axis].end();
1035	    if(alreadyEnabled != enabled) {
1036	        if(enabled) {
1037	            tracesAxis[axis].insert(t);
1038	        } else {
1039	            tracesAxis[axis].erase(t);
1040	            if(axis == 0) {
1041	                disconnect(t, &Trace::markerAdded, this, &TraceXYPlot::markerAdded);
1042	                disconnect(t, &Trace::markerRemoved, this, &TraceXYPlot::markerRemoved);
1043	                auto tracemarkers = t->getMarkers();
1044	                for(auto m : tracemarkers) {
1045	                    markerRemoved(m);
1046	                }
1047	            }
1048	        }
1049	
1050	        updateContextMenu();
1051	        replot();
1052	    }
1053	}
