1055	bool TraceXYPlot::domainMatch(Trace *t)
1056	{
1057	    switch(xAxis.getType()) {
1058	    case XAxis::Type::Frequency:
1059	        return t->outputType() == Trace::DataType::Frequency;
1060	    case XAxis::Type::Distance:
1061	    case XAxis::Type::Time:
1062	        return t->outputType() == Trace::DataType::Time;
1063	    case XAxis::Type::Power:
1064	        return t->outputType() == Trace::DataType::Power;
1065	    case XAxis::Type::TimeZeroSpan:
1066	        return t->outputType() == Trace::DataType::TimeZeroSpan;
1067	    case XAxis::Type::Last:
1068	        return false;
1069	    }
1070	    return false;
1071	}
