1073	bool TraceXYPlot::supported(Trace *t, YAxis::Type type)
1074	{
1075	    if(!domainMatch(t)) {
1076	        return false;
1077	    }
1078	
1079	    switch(type) {
1080	    case YAxis::Type::Disabled:
1081	        return false;
1082	    case YAxis::Type::VSWR:
1083	    case YAxis::Type::SeriesR:
1084	    case YAxis::Type::Reactance:
1085	    case YAxis::Type::Capacitance:
1086	    case YAxis::Type::Inductance:
1087	    case YAxis::Type::QualityFactor:
1088	    case YAxis::Type::AbsImpedance:
1089	        if(!t->isReflection()) {
1090	            return false;
1091	        }
1092	        break;
1093	    default:
1094	        break;
1095	    }
1096	    return true;
