97	void TraceWaterfall::fromJSON(nlohmann::json j)
98	{
99	    parseBaseJSON(j);
100	    resetWaterfall();
101	    pixelsPerLine = j.value("pixelsPerLine", pixelsPerLine);
102	    maxDataSweeps = j.value("maxLines", maxDataSweeps);
103	    keepDataBeyondPlotSize = j.value("keepDataBeyondPlot", keepDataBeyondPlotSize);
104	    if(QString::fromStdString(j.value("direction", "TopToBottom")) == "TopToBottom") {
105	        dir = Direction::TopToBottom;
106	    } else {
107	        dir = Direction::BottomToTop;
108	    }
109	    align = AlignmentFromString(QString::fromStdString(j.value("alignment", "")));
110	    if(align == Alignment::Last) {
111	        align = Alignment::PrimaryOnly;
112	    }
113	
114	    for(unsigned int hash : j["traces"]) {
115	        // attempt to find the traces with this hash
116	        bool found = false;
117	        for(auto t : model.getTraces()) {
118	            if(t->toHash() == hash) {
119	                enableTrace(t, true);
120	                found = true;
121	                break;
122	            }
123	        }
124	        if(!found) {
125	            qWarning() << "Unable to find trace with hash" << hash;
126	        }
127	    }
128	}
