162	bool TraceWaterfall::configureForTrace(Trace *t)
163	{
164	    YAxis::Type yDefault = YAxis::Type::Disabled;
165	
166	    switch(t->outputType()) {
167	    case Trace::DataType::Frequency:
168	        xAxis.set(XAxis::Type::Frequency, false, true, 0, 1, 10, false);
169	        yDefault = YAxis::Type::Magnitude;
170	        break;
171	    case Trace::DataType::Power:
172	        xAxis.set(XAxis::Type::Power, false, true, 0, 1, 10, false);
173	        yDefault = YAxis::Type::Magnitude;
174	        break;
175	    case Trace::DataType::Time:
176	    case Trace::DataType::TimeZeroSpan:
177	    case Trace::DataType::Invalid:
178	        // unable to add
179	        return false;
180	    }
181	    if(!yAxis.isSupported(xAxis.getType(), getModel().getSource())) {
182	        yAxis.set(yDefault, false, true, 0, 1, 10, false);
183	    }
184	    traceRemovalPending = true;
185	    return true;
186	}
