188	bool TraceWaterfall::domainMatch(Trace *t)
189	{
190	    switch(xAxis.getType()) {
191	    case XAxis::Type::Frequency:
192	        return t->outputType() == Trace::DataType::Frequency;
193	    case XAxis::Type::Distance:
194	    case XAxis::Type::Time:
195	        return t->outputType() == Trace::DataType::Time;
196	    case XAxis::Type::Power:
197	        return t->outputType() == Trace::DataType::Power;
198	    case XAxis::Type::TimeZeroSpan:
199	        return t->outputType() == Trace::DataType::TimeZeroSpan;
200	    case XAxis::Type::Last:
201	        return false;
202	    }
203	    return false;
204	}
