240	void TraceWaterfall::draw(QPainter &p)
241	{
242	    auto& pref = Preferences::getInstance();
243	
244	    int xAxisSpace = pref.Graphs.fontSizeAxis * 3;
245	    constexpr int topMargin = 10;
246	    auto w = p.window();
247	    auto pen = QPen(pref.Graphs.Color.axis, 0);
248	    pen.setCosmetic(true);
249	    p.setPen(pen);
250	
251	    auto leftMargin = TraceXYPlot::sideMargin(align == Alignment::PrimaryOnly || align == Alignment::BothAxes);
252	    auto rightMargin = TraceXYPlot::sideMargin(align == Alignment::SecondaryOnly || align == Alignment::BothAxes);
253	    auto plotRect = QRect(leftMargin, topMargin, w.width() - leftMargin - rightMargin, w.height()-topMargin-xAxisSpace);
254	
255	    plotAreaTop = plotRect.y();
256	    plotAreaLeft = plotRect.x();
257	    plotAreaWidth = plotRect.width();
258	    plotAreaBottom = plotRect.y()+plotRect.height();
259	
260	    // draw Y legend
261	    auto font = p.font();
262	    font.setPixelSize(pref.Graphs.fontSizeAxis);
263	    p.setFont(font);
264	    QRect legendRect;
265	    constexpr int legendMargin = 10;
266	    if(leftMargin < rightMargin) {
267	        legendRect = QRect(QPoint(plotRect.x()+plotRect.width()+legendMargin, plotAreaTop), QPoint(width() - legendMargin, plotAreaBottom));
268	    } else {
269	        legendRect = QRect(QPoint(legendMargin, plotAreaTop), QPoint(leftMargin - legendMargin, plotAreaBottom));
270	    }
271	    p.drawRect(legendRect);
272	    for(int i=plotAreaTop + 1;i<plotAreaBottom;i++) {
273	        auto color = Util::getIntensityGradeColor(Util::Scale<double>(i, plotAreaTop, plotAreaBottom, 1.0, 0.0));
274	        p.setPen(QColor(color));
275	        pen.setCosmetic(true);
276	        p.drawLine(legendRect.x()+1, i, legendRect.x()+legendRect.width()-1, i);
277	    }
278	    QString unit = "";
279	    if(pref.Graphs.showUnits) {
280	        unit = yAxis.Unit(getModel().getSource());
281	    }
282	    QString labelMin = Unit::ToString(yAxis.getRangeMin(), unit, yAxis.Prefixes(getModel().getSource()), 4);
283	    QString labelMax = Unit::ToString(yAxis.getRangeMax(), unit, yAxis.Prefixes(getModel().getSource()), 4);
284	    p.setPen(QPen(pref.Graphs.Color.axis, 1));
285	    p.save();
286	    p.translate(legendRect.x(), w.height());
287	    p.rotate(-90);
288	    p.drawText(QRect(xAxisSpace + 10, 0, plotAreaBottom - plotAreaTop - 20, legendRect.width()), Qt::AlignRight | Qt::AlignVCenter, labelMax);
289	    p.drawText(QRect(xAxisSpace + 10, 0, plotAreaBottom - plotAreaTop - 20, legendRect.width()), Qt::AlignLeft | Qt::AlignVCenter, labelMin);
290	    p.drawText(QRect(xAxisSpace + 10, 0, plotAreaBottom - plotAreaTop - 20, legendRect.width()), Qt::AlignHCenter | Qt::AlignVCenter, yAxis.TypeToName());
291	    p.restore();
292	
293	
294	    pen = QPen(pref.Graphs.Color.axis, 0);
295	    pen.setCosmetic(true);
296	    p.setPen(pen);
297	    p.drawRect(plotRect);
298	
299	    // draw axis types
300	    p.drawText(QRect(0, w.height()-pref.Graphs.fontSizeAxis*1.5, w.width(), pref.Graphs.fontSizeAxis*1.5), Qt::AlignHCenter, xAxis.TypeToName());
301	
302	    if(xAxis.getTicks().size() >= 1) {
303	        // draw X ticks
304	        int significantDigits;
305	        bool displayFullFreq;
306	        if(xAxis.getLog()) {
307	            significantDigits = 5;
308	            displayFullFreq = true;
309	        } else {
310	            // this only works for evenly distributed ticks:
311	            auto max = qMax(abs(xAxis.getTicks().front()), abs(xAxis.getTicks().back()));
312	            double step;
313	            if(xAxis.getTicks().size() >= 2) {
314	                step = abs(xAxis.getTicks()[0] - xAxis.getTicks()[1]);
315	            } else {
316	                // only one tick, set arbitrary number of digits
317	                step = max / 1000;
318	            }
319	            significantDigits = floor(log10(max)) - floor(log10(step)) + 1;
320	            displayFullFreq = significantDigits <= 5;
321	        }
322	        constexpr int displayLastDigits = 4;
323	        QString prefixes = "fpnum kMG";
324	        QString unit = "";
325	        if(pref.Graphs.showUnits) {
326	            unit = xAxis.Unit();
327	        }
328	        QString commonPrefix = QString();
329	        if(!displayFullFreq) {
330	            auto fullFreq = Unit::ToString(xAxis.getTicks().front(), unit, prefixes, significantDigits);
331	            commonPrefix = fullFreq.at(fullFreq.size() - 1);
332	            auto front = fullFreq;
333	            front.truncate(fullFreq.size() - displayLastDigits - unit.length());
334	            auto back = fullFreq;
335	            back.remove(0, front.size());
336	            back.append("..");
337	            p.setPen(QPen(QColor("orange")));
338	            QRect bounding;
339	            p.drawText(QRect(2, plotAreaBottom + pref.Graphs.fontSizeAxis + 5, w.width(), pref.Graphs.fontSizeAxis*1.5), 0, front, &bounding);
340	            p.setPen(pref.Graphs.Color.axis);
341	            p.drawText(QRect(bounding.x() + bounding.width(), plotAreaBottom + pref.Graphs.fontSizeAxis + 5, w.width(), pref.Graphs.fontSizeAxis*1.5), 0, back);
342	        }
343	
344	        int lastTickLabelEnd = 0;
345	        for(auto t : xAxis.getTicks()) {
346	            auto xCoord = xAxis.transform(t, plotAreaLeft, plotAreaLeft + plotAreaWidth);
347	            p.setPen(QPen(pref.Graphs.Color.axis, 1));
348	            p.drawLine(xCoord, plotAreaBottom, xCoord, plotAreaBottom + 2);
349	            if(xCoord != plotAreaLeft && xCoord != plotAreaLeft + plotAreaWidth) {
350	                p.setPen(QPen(pref.Graphs.Color.Ticks.divisions, 0.5, Qt::DashLine));
351	                p.drawLine(xCoord, plotAreaTop, xCoord, plotAreaBottom);
352	            }
353	            if(xCoord - 40 <= lastTickLabelEnd) {
354	                // would overlap previous tick label, skip
355	                continue;
356	            }
357	            auto tickValue = Unit::ToString(t, unit, prefixes, significantDigits);
358	            p.setPen(QPen(pref.Graphs.Color.axis, 1));
359	            if(displayFullFreq) {
360	                QRect bounding;
361	                p.drawText(QRect(xCoord - pref.Graphs.fontSizeAxis*4, plotAreaBottom + 5, pref.Graphs.fontSizeAxis*8,
362	                                 pref.Graphs.fontSizeAxis*1.5), Qt::AlignHCenter, tickValue, &bounding);
363	                lastTickLabelEnd = bounding.x() + bounding.width();
364	            } else {
365	                // check if the same prefix was used as in the fullFreq string
366	                if(tickValue.at(tickValue.size() - 1) != commonPrefix) {
367	                    // prefix changed, we reached the next order of magnitude. Force same prefix as in fullFreq and add extra digit
368	                    tickValue = Unit::ToString(t, "", commonPrefix, significantDigits + 1);
369	                }
370	
371	                tickValue.remove(0, tickValue.size() - displayLastDigits - unit.length());
372	                QRect bounding;
373	                p.drawText(QRect(xCoord - pref.Graphs.fontSizeAxis*4, plotAreaBottom + 5, pref.Graphs.fontSizeAxis*8, pref.Graphs.fontSizeAxis*1.5), Qt::AlignHCenter, tickValue, &bounding);
374	                lastTickLabelEnd = bounding.x() + bounding.width();
375	                p.setPen(QPen(QColor("orange")));
376	                p.drawText(QRect(0, plotAreaBottom + 5, bounding.x() - 1, pref.Graphs.fontSizeAxis*1.5), Qt::AlignRight, "..", &bounding);
377	            }
378	        }
379	    }
380	
381	    p.setClipRect(QRect(plotRect.x()+1, plotRect.y()+1, plotRect.width()-1, plotRect.height()-1));
382	    if(data.size()) {
383	        // plot waterfall data
384	        int ytop, ybottom;
385	        bool lastLine = false;
386	        if(dir == Direction::TopToBottom) {
387	            ytop = plotAreaTop;
388	            ybottom = ytop + pixelsPerLine - 1;
389	        } else {
390	            ybottom = plotAreaBottom - 1;
391	            ytop = ybottom - pixelsPerLine + 1;
392	        }
393	        int i;
394	        for(i=data.size() - 1;i>=0;i--) {
395	            auto sweep = data[i];
396	            for(unsigned int s=0;s<sweep.size();s++) {
397	                auto x = xAxis.sampleToCoordinate(sweep[s], trace);
398	                double x_start;
399	                double x_stop;
400	                if(x < xAxis.getRangeMin() || x > xAxis.getRangeMax()) {
401	                    // out of range, skip
402	                    continue;
403	                }
404	                if(s == 0) {
405	                    x_start = x;
406	                } else {
407	                    auto prev_x = xAxis.sampleToCoordinate(sweep[s-1], trace);
408	                    x_start = (prev_x + x) / 2.0;
409	                }
410	                x_start = xAxis.transform(x_start, plotAreaLeft, plotAreaLeft + plotAreaWidth);
411	                if(s == sweep.size() - 1) {
412	                    x_stop = x;
413	                } else {
414	                    auto next_x = xAxis.sampleToCoordinate(sweep[s+1], trace);
415	                    x_stop = (next_x + x) / 2.0;
416	                }
417	                x_stop = xAxis.transform(x_stop, plotAreaLeft, plotAreaLeft + plotAreaWidth);
418	                auto y = yAxis.sampleToCoordinate(sweep[s]);
419	                auto color = Util::getIntensityGradeColor(yAxis.transform(y, 0.0, 1.0));
420	                auto rect = QRect(round(x_start), ytop, round(x_stop - x_start) + 1, ybottom - ytop + 1);
421	                p.fillRect(rect, QBrush(color));
422	            }
423	            if(lastLine) {
424	                break;
425	            }
426	            // update ycoords for next line
427	            if(dir == Direction::TopToBottom) {
428	                ytop = ybottom + 1;
429	                ybottom = ytop + pixelsPerLine - 1;
430	                if(ybottom >= plotAreaBottom) {
431	                    ybottom = plotAreaBottom;
432	                    lastLine = true;
433	                }
434	            } else {
435	                ybottom = ytop - 1;
436	                ytop = ybottom - pixelsPerLine + 1;
437	                if(ytop <= plotAreaTop) {
438	                    ytop = plotAreaTop;
439	                    lastLine = true;
440	                }
441	            }
442	        }
443	        if(!keepDataBeyondPlotSize && i >= 0) {
444	            // not all data could be plotted, drop
445	            data.erase(data.begin(), data.begin() + i);
446	            updateYAxis();
447	        }
448	    }
449	    p.setClipping(false);
450	
451	    // show sweep indicator if activated
452	    if((xAxis.getType() == XAxis::Type::Frequency || xAxis.getType() == XAxis::Type::TimeZeroSpan || xAxis.getType() == XAxis::Type::Power)
453	            && !isnan(xSweep)) {
454	        if(xSweep >= xAxis.getRangeMin() && xSweep <= xAxis.getRangeMax()) {
455	            auto xpos = xAxis.transform(xSweep, plotAreaLeft, plotAreaLeft + plotAreaWidth);
456	            pen = QPen(pref.Graphs.Color.axis);
457	            pen.setCosmetic(true);
458	            p.setPen(pen);
459	            if(pref.Graphs.SweepIndicator.line) {
460	                p.drawLine(xpos, plotAreaTop, xpos, plotAreaBottom);
461	            }
462	            if(pref.Graphs.SweepIndicator.triangle) {
463	                for(int i=0;i<pref.Graphs.SweepIndicator.triangleSize;i++) {
464	                    p.drawLine(xpos - i,plotAreaBottom+i+1, xpos + i, plotAreaBottom+i+1);
465	                }
466	            }
467	        }
468	    }
469	
470	    if(dropPending) {
471	        p.setOpacity(dropOpacity);
472	        p.setBrush(dropBackgroundColor);
473	        p.setPen(dropForegroundColor);
474	        // show drop area over whole plot
475	        p.drawRect(getDropRect());
476	        auto font = p.font();
477	        font.setPixelSize(20);
478	        p.setFont(font);
479	        p.setOpacity(1.0);
480	        p.setPen(dropSection == DropSection::OnPlot ? dropHighlightColor : dropForegroundColor);
481	        auto text = "Drop here to add\n" + dropTrace->name() + "\nto waterfall plot";
482	        p.drawText(getDropRect(), Qt::AlignCenter, text);
483	    }
