544	void TraceWaterfall::traceDataChanged(unsigned int begin, unsigned int end)
545	{
546	    if(xAxis.getAutorange()) {
547	        double min_x = trace->sample(0).x;
548	        double max_x = trace->sample(trace->size() - 1).x;
549	        if(min_x != xAxis.getRangeMin() || max_x != xAxis.getRangeMax()) {
550	            resetWaterfall();
551	            // adjust axis
552	            xAxis.set(xAxis.getType(), xAxis.getLog(), true, min_x, max_x, xAxis.getDivs(), xAxis.getAutoDivs());
553	        }
554	    }
555	    bool YAxisUpdateRequired = false;
556	    if (begin == 0 || data.size() == 0) {
557	        if(data.size() == 1) {
558	            YAxisUpdateRequired = true;
559	        }
560	        // start new row
561	        data.push_back(std::vector<Trace::Data>());
562	        while (data.size() > maxDataSweeps) {
563	            data.pop_front();
564	            // min/max might have changed due to removed data
565	            YAxisUpdateRequired = true;
566	        }
567	    }
568	    // grab trace data
569	    data.back().resize(trace->size());
570	    double min = yAxis.getRangeMin();
571	    double max = yAxis.getRangeMax();
572	    for(unsigned int i=begin;i<end;i++) {
573	        data.back()[i] = trace->sample(i);
574	        if(yAxis.getAutorange() && !YAxisUpdateRequired) {
575	            double val = yAxis.sampleToCoordinate(trace->sample(i));
576	            if(isnan(val) || isinf(val)) {
577	                continue;
578	            }
579	            if(val < min) {
580	                min = val;
581	            }
582	            if(val > max) {
583	                max = val;
584	            }
585	        }
586	    }
587	    if(yAxis.getAutorange() && !YAxisUpdateRequired && (min != yAxis.getRangeMin() || max != yAxis.getRangeMax())) {
588	        // axis scaling needs update due to new trace data
589	        yAxis.set(yAxis.getType(), yAxis.getLog(), true, min, max, yAxis.getDivs(), yAxis.getAutoDivs());
590	    } else if(YAxisUpdateRequired) {
591	        updateYAxis();
592	    }
593	}
594	
595	void TraceWaterfall::updateYAxis()
596	{
597	    if(yAxis.getAutorange()) {
598	        double min = std::numeric_limits<double>::max();
599	        double max = std::numeric_limits<double>::lowest();
600	        for(auto sweep : data) {
601	            for(unsigned int i=0;i<sweep.size();i++) {
602	                double val = yAxis.sampleToCoordinate(sweep[i]);
603	                if(isnan(val) || isinf(val)) {
604	                    continue;
605	                }
606	                if(val < min) {
607	                    min = val;
608	                }
609	                if(val > max) {
610	                    max = val;
611	                }
612	            }
613	        }
614	        if(max > min) {
615	            yAxis.set(yAxis.getType(), yAxis.getLog(), true, min, max, yAxis.getDivs(), yAxis.getAutoDivs());
616	        }
617	    }
618	}
